export function pick(obj, claves) {
  const pares = claves
    .filter((clave) => /* ¿existe en obj? */)
    .map((clave) => [clave, obj[clave]]);
  return Object.fromEntries(pares);
}

export function omit(obj, claves) {
  const pares = Object.entries(obj).filter(([clave]) => /* ¿NO está en claves? */);
  return Object.fromEntries(pares);
}
